#!/usr/bin/env node
// Builds the CodeMirror bundle served at
// /custom-mobile-compat/text-editor/codemirror.bundle.js
//
// Output:
//   src/applications/custom-mobile-compat/assets/codemirror.bundle.js
//
// Run:  node scripts/build-nc-text-editor.mjs
// Or:   npm run build:nc-text-editor
//
// The bundle is committed to git so the deployed server has it without
// running the build at deploy time. Re-run when CodeMirror or one of the
// language packages is bumped, then commit the regenerated file.
//
// The page renderer (utils/text-editor-page.ts) loads the bundle via
// dynamic `import(bundleUrl)`, so we emit ESM with a named `mountCodeMirror`
// export. The source file also pins `window.NcTextEditor.mountCodeMirror`
// as a belt-and-suspenders fallback in case the loader finds the global
// before the import resolves.

import { build } from 'esbuild'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const ENTRY = join(ROOT, 'scripts', 'nc-text-editor-src', 'index.js')
const OUT = join(ROOT, 'src', 'applications', 'custom-mobile-compat', 'assets', 'codemirror.bundle.js')

await build({
  entryPoints: [ENTRY],
  outfile: OUT,
  bundle: true,
  format: 'esm',
  // safari15 is the floor for full destructuring support in esbuild's
  // transform tables (some CM packages rely on it). NC iOS 33.x requires
  // iOS 16+ which ships Safari 16, so we're well within the support window.
  target: ['es2022', 'safari15'],
  minify: true,
  sourcemap: false,
  // Inline the small CodeMirror CSS files. CM ships its own styles via JS,
  // so we don't actually need a separate .css output.
  loader: { '.css': 'text' },
  legalComments: 'none',
  banner: { js: '/* CodeMirror bundle for Sync-in NC text editor — generated by scripts/build-nc-text-editor.mjs */' }
})

console.log(`Built ${OUT}`)
